{"output": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageNumber, PageBreak, LevelFormat, TabStopType, TabStopPosition,
  Header, Footer, ExternalHyperlink
} = require('docx');
const fs = require('fs');

// ── Color palette ─────────────────────────────────────────────────────────────
const C = {
  purple:     '4F46E5',
  purpleLight:'EEF2FF',
  teal:       '0F766E',
  tealLight:  'F0FDFA',
  amber:      'B45309',
  amberLight: 'FFFBEB',
  red:        'B91C1C',
  redLight:   'FEF2F2',
  gray:       '374151',
  grayLight:  'F9FAFB',
  grayMid:    'E5E7EB',
  white:      'FFFFFF',
  black:      '111827',
  blue:       '1D4ED8',
  blueLight:  'EFF6FF',
  green:      '15803D',
  greenLight: 'F0FDF4',
};

// ── Border helpers ─────────────────────────────────────────────────────────────
const border = (color = 'E5E7EB', size = 1) => ({
  style: BorderStyle.SINGLE, size, color
});
const cellBorders = (color = 'E5E7EB') => ({
  top: border(color), bottom: border(color),
  left: border(color), right: border(color)
});
const noBorder = () => ({
  style: BorderStyle.NONE, size: 0, color: 'FFFFFF'
});
const allNoBorder = () => ({
  top: noBorder(), bottom: noBorder(),
  left: noBorder(), right: noBorder()
});

// ── Text helpers ──────────────────────────────────────────────────────────────
const run = (text, opts = {}) => new TextRun({
  text, font: 'Consolas',
  size: opts.size || 20,
  bold: opts.bold || false,
  color: opts.color || C.black,
  ...opts
});

const prose = (text, opts = {}) => new TextRun({
  text, font: 'Arial',
  size: opts.size || 22,
  bold: opts.bold || false,
  color: opts.color || C.black,
  italics: opts.italics || false,
});

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: C.purple, space: 6 } },
  children: [new TextRun({ text, font: 'Arial', size: 36, bold: true, color: C.purple })]
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 280, after: 120 },
  children: [new TextRun({ text, font: 'Arial', size: 28, bold: true, color: C.gray })]
});

const h3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 200, after: 80 },
  children: [new TextRun({ text, font: 'Arial', size: 24, bold: true, color: C.teal })]
});

const p = (text, opts = {}) => new Paragraph({
  spacing: { after: 120, line: 276 },
  alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  children: [prose(text, opts)]
});

const pMixed = (...children) => new Paragraph({
  spacing: { after: 120, line: 276 },
  children
});

const space = (n = 1) => new Paragraph({
  spacing: { after: n * 80 },
  children: [prose('')]
});

const rule = () => new Paragraph({
  spacing: { before: 160, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: C.grayMid } },", "exit_code": 0, "error": null}

